#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <stdexcept>
#include <vector>
#include "q1_moe_hawkeye_bf16_accumulator.h"
#include "bf16_midpoint_selector.h"
float fp(uint32_t bits){float value;std::memcpy(&value,&bits,4u);return value;}
uint32_t raw(float value){uint32_t bits;std::memcpy(&bits,&value,4u);return bits;}
std::vector<uint16_t> read(const char* path,unsigned k){
 std::ifstream f(path,std::ios::binary|std::ios::ate);
 if(!f || f.tellg()!=std::streamoff(k*2u))throw std::runtime_error("operand size");
 std::vector<uint16_t> result(k);f.seekg(0);if(!f.read(reinterpret_cast<char*>(result.data()),k*2u))throw std::runtime_error("operand read");return result;
}
int main(int argc,char** argv){
 if(argc!=10)return 1;
 const unsigned k=unsigned(std::strtoul(argv[3],nullptr,10));
 const auto a=read(argv[1],k),b=read(argv[2],k);
 const float p=fp(uint32_t(std::strtoul(argv[4],nullptr,16))),s=fp(uint32_t(std::strtoul(argv[5],nullptr,16)));
 const float x=fp(uint32_t(std::strtoul(argv[6],nullptr,16))),w=fp(uint32_t(std::strtoul(argv[7],nullptr,16)));
 const unsigned radius=unsigned(std::strtoul(argv[8],nullptr,10)),ppb=unsigned(std::strtoul(argv[9],nullptr,10));
 const float scale=float(ppb)*1.0e-9f,cauchy=x*w,old_error=cauchy*scale,new_error=s*scale;
 const float canonical=qrt_q1_moe_hawkeye::accumulate_bf16_hopper_blackwell(0.0f,a.data(),b.data(),k);
 const unsigned low=raw(p)&65535u,distance=low>=32768u?low-32768u:32768u-low;
 const bool radius_selected=distance<=radius,small=((raw(p)>>23u)&255u)<32u;
 const bool old_selected=radius_selected||small||qrt_bf16_midpoint::within_error(p,old_error);
 const bool new_selected=radius_selected||small||qrt_bf16_midpoint::within_error(p,new_error);
 const uint32_t pword=raw(p),cword=raw(canonical);
 const unsigned pb=(pword+0x7fffu+((pword>>16u)&1u))>>16u,cb=(cword+0x7fffu+((cword>>16u)&1u))>>16u;
 std::printf("{\"canonical_bits\":\"%08x\",\"producer_bf16\":\"%04x\",\"canonical_bf16\":\"%04x\",\"midpoint_distance\":%.17g,\"cauchy_bound\":%.17g,\"old_error_bound\":%.17g,\"new_error_bound\":%.17g,\"midpoint_ulp_distance\":%u,\"old_selected\":%s,\"new_selected\":%s}\n",raw(canonical),pb,cb,double(qrt_bf16_midpoint::nearest_distance(p)),double(cauchy),double(old_error),double(new_error),distance,old_selected?"true":"false",new_selected?"true":"false");
 return 0;
}
